{
  "links": [
    {
      "href": "https://github.com/example-health/scheduling/pull/219",
      "text": "PR #219: longer slot cache TTL"
    }
  ],
  "payload": {
    "custom_details": {
      "change_type": "configuration",
      "cluster": "reinvent-kind",
      "config_changes": "BOOKING_SLOT_CACHE_TTL 30s → 60s. No dependency or resource changes.",
      "deployed_by": "ci-bot (merge of PR #219 'longer slot cache to cut DB reads')",
      "deployment": "scheduling",
      "image": "registry.internal/clinic/scheduling:v5.2.0",
      "namespace": "payments",
      "platform": "kubernetes",
      "previous_image": "registry.internal/clinic/scheduling:v3.8.1",
      "resources_changed": "none - memory limit unchanged at 64Mi",
      "rollout": "RollingUpdate, 1/1 replicas updated, healthy for 3h before the incident",
      "service": "scheduling"
    },
    "source": "argocd/reinvent-kind",
    "summary": "Deployed scheduling v5.2.0 to reinvent-kind/payments: booking slot cache TTL 30s → 60s (config only)",
    "timestamp": "{{s01_ts1}}"
  },
  "routing_key": "{{change_key_scheduling}}"
}

{
  "links": [
    {
      "href": "https://github.com/example-health/payment-api/pull/482",
      "text": "PR #482: bump x12-claims-parser to 5.0.0"
    },
    {
      "href": "https://github.com/example-health/payment-api/releases/tag/v2.14.0",
      "text": "Release v2.14.0"
    }
  ],
  "payload": {
    "custom_details": {
      "change_type": "dependency upgrade",
      "cluster": "reinvent-kind",
      "dependency_changes": "x12-claims-parser 4.2.1 → 5.0.0 (major). Release notes: streaming segment parser now pools buffers per payer connection.",
      "deployed_by": "ci-bot (merge of PR #482 'bump x12-claims-parser to 5.x')",
      "deployment": "payment-api",
      "image": "registry.internal/claims/payment-api:v2.14.0",
      "namespace": "payments",
      "platform": "kubernetes",
      "previous_image": "registry.internal/claims/payment-api:v2.13.4",
      "resources_changed": "none - container still has no memory limit",
      "rollout": "RollingUpdate, 1/1 replicas updated",
      "service": "payment-api"
    },
    "source": "argocd/reinvent-kind",
    "summary": "Deployed payment-api v2.14.0 to reinvent-kind/payments: upgrades x12-claims-parser 4.2.1 → 5.0.0",
    "timestamp": "{{s02_ts1}}"
  },
  "routing_key": "{{change_key_claims_reconciliation}}"
}

{
  "dedup_key": "reinvent/payments/payment-api/probe-latency/{{run_id}}",
  "event_action": "trigger",
  "payload": {
    "class": "probe_latency",
    "component": "payment-api",
    "custom_details": {
      "cluster": "reinvent-kind",
      "note": "Info-level noise. The Event Orchestration suppresses it, so it never pages anyone.",
      "platform": "kubernetes",
      "service": "payment-api"
    },
    "group": "payments",
    "severity": "info",
    "source": "reinvent-control-plane",
    "summary": "Kubernetes: liveness probe latency 1.2s on payment-api (threshold 1s)"
  },
  "routing_key": "{{orchestration_routing_key}}"
}

{
  "dedup_key": "reinvent/payments/payment-api/probe-latency/{{run_id}}",
  "event_action": "resolve",
  "payload": {
    "class": "probe_latency",
    "component": "payment-api",
    "custom_details": {
      "cluster": "reinvent-kind",
      "note": "Info-level noise. The Event Orchestration suppresses it, so it never pages anyone.",
      "platform": "kubernetes",
      "service": "payment-api"
    },
    "group": "payments",
    "severity": "info",
    "source": "reinvent-control-plane",
    "summary": "Kubernetes: liveness probe latency 1.2s on payment-api (threshold 1s)"
  },
  "routing_key": "{{orchestration_routing_key}}"
}
